class Solution {
public:
    string reverseOnlyLetters(string s) {
        int lo = 0, hi = (int)s.length() - 1;
        while (lo < hi) {
            if (!isalpha(s[lo])) lo++;
            else if (!isalpha(s[hi])) hi--;
            else swap(s[lo++], s[hi--]);
        }
        return s;
    }
};

class Solution {
    public String reverseOnlyLetters(String s) {
        char[] arr = s.toCharArray();
        int lo = 0, hi = arr.length - 1;
        while (lo < hi) {
            if (!Character.isLetter(arr[lo])) lo++;
            else if (!Character.isLetter(arr[hi])) hi--;
            else {
                char tmp = arr[lo];
                arr[lo] = arr[hi];
                arr[hi] = tmp;
                lo++;
                hi--;
            }
        }
        return new String(arr);
    }
}

var reverseOnlyLetters = function(s) {
    const arr = s.split('');
    let lo = 0, hi = arr.length - 1;
    while (lo < hi) {
        if (!/[a-zA-Z]/.test(arr[lo])) lo++;
        else if (!/[a-zA-Z]/.test(arr[hi])) hi--;
        else {
            const tmp = arr[lo];
            arr[lo] = arr[hi];
            arr[hi] = tmp;
            lo++;
            hi--;
        }
    }
    return arr.join('');
};
